def main():
    if not TARGET.exists():
        raise SystemExit(f"❌ не найден: {TARGET}")

    src = TARGET.read_text(encoding="utf-8")

    if MARKER in src:
        print(f"✓ {MARKER} уже применён — пропуск (идемпотентно).")
        return

    if OLD_BLOCK not in src:
        raise SystemExit("❌ якорь (блок Сито-1/Сито-2) не найден — файл "
                          "разошёлся с ожидаемым, патч НЕ применён")
    if OLD_VERDICT not in src:
        raise SystemExit("❌ якорь (блок РАЗВИЛКИ) не найден — файл "
                          "разошёлся с ожидаемым, патч НЕ применён")

    src = src.replace(OLD_BLOCK, NEW_BLOCK, 1)
    src = src.replace(OLD_VERDICT, NEW_VERDICT, 1)

    try:
        ast.parse(src)
    except SyntaxError as e:
        raise SystemExit(f"❌ патч ломает синтаксис: {e} — файл НЕ тронут")

    backup = TARGET.with_suffix(".py.bak_sliyanie")
    shutil.copy2(TARGET, backup)
    TARGET.write_text(src, encoding="utf-8")
    print(f"✓ записано: {TARGET}")
    print(f"✓ бэкап:    {backup}")

    py_compile.compile(str(TARGET), doraise=True)
    print(f"✓ py_compile прошёл")
    print(f"✓ {MARKER} применён")
    print("")
    print("⚠️  НАПОМИНАНИЕ: первый прогон после патча — на коротком")
    print("   отрезке истории (--signals 1), сверить лог глазами.")


if __name__ == "__main__":
    main()
